use xiom.io;

type Account = {
  owner: Str;
  balance: Float64;
}

fn Account.deposit(self, amount: Float64) {
  balance = balance + amount;
}

fn Account.withdraw(self, amount: Float64) -> Bool {
  if balance >= amount {
    balance = balance - amount;
    return true;
  }
  return false;
}

fn main() -> Int {
  let acc = Account{ owner: "Alex", balance: 100.0 };
  acc.deposit(25.0);
  acc.withdraw(40.0);
  io.println(acc.balance.to_str());
  return 0;
}
